#!/usr/bin/env python3
"""Restore a directory tree produced by ``compress.py``.

Usage:
    python /app/decompress.py <resharded_dir>

The command works in place: shards inside ``<resharded_dir>/.reshard`` are
replayed into ``<resharded_dir>``, then the ``.reshard`` directory is removed,
leaving exactly the original tree.
"""

from __future__ import annotations

import json
import os
import shutil
import stat
import struct
import sys

MAGIC = b"KODRESH1\n"
MARKER_NAME = "reshard.json"
RESERVED_PREFIX = ".reshard"
MARKER_FORMAT = "kodact-reshard"

RECORD = struct.Struct("<cIIqQQQ")

TYPE_FILE = b"F"
TYPE_DIR = b"D"
TYPE_LINK = b"L"


def find_reserved_dir(root: str) -> str:
    """Find the single reserved directory containing our marker file."""
    candidates: list[str] = []
    try:
        entries = sorted(os.scandir(root), key=lambda entry: entry.name)
    except OSError as exc:
        raise SystemExit(f"error: cannot read directory {root}: {exc}")

    for entry in entries:
        if not entry.name.startswith(RESERVED_PREFIX):
            continue
        if not entry.is_dir(follow_symlinks=False):
            continue
        marker_path = os.path.join(entry.path, MARKER_NAME)
        try:
            with open(marker_path, "r", encoding="utf-8") as fh:
                marker = json.load(fh)
        except (OSError, ValueError):
            continue
        if isinstance(marker, dict) and marker.get("format") == MARKER_FORMAT:
            candidates.append(entry.path)

    if not candidates:
        raise SystemExit(
            f"error: no resharded data found in {root!r} "
            f"(expected a {RESERVED_PREFIX}*/{MARKER_NAME})"
        )
    if len(candidates) > 1:
        raise SystemExit(
            "error: multiple resharded data sets found: "
            + ", ".join(candidates)
        )
    return candidates[0]


def safe_join(root: str, rel_path: str) -> str:
    """Join a record path to root, refusing absolute or escaping paths."""
    if not rel_path or rel_path.startswith("/"):
        raise ValueError(f"invalid path in shard: {rel_path!r}")
    parts = rel_path.split("/")
    if any(part in ("", ".", "..") for part in parts):
        raise ValueError(f"invalid path in shard: {rel_path!r}")
    return os.path.join(root, *parts)


def collect_shards(reserved_dir: str) -> list[str]:
    shards: list[tuple[str, str]] = []
    for dirpath, dirnames, filenames in os.walk(reserved_dir):
        dirnames.sort()
        for filename in filenames:
            if filename == MARKER_NAME:
                continue
            if not filename.endswith(".kod"):
                continue
            path = os.path.join(dirpath, filename)
            rel_path = os.path.relpath(path, reserved_dir).replace(os.sep, "/")
            shards.append((rel_path, path))
    shards.sort()
    return [path for _rel_path, path in shards]


def create_symlink(path: str, target: str) -> None:
    if os.path.lexists(path):
        os.remove(path)
    os.symlink(target, path)


def main(argv: list[str]) -> int:
    if len(argv) != 2:
        print(f"usage: {argv[0]} <resharded_dir>", file=sys.stderr)
        return 2

    root = os.path.abspath(argv[1])
    if not os.path.isdir(root):
        print(f"error: not a directory: {root}", file=sys.stderr)
        return 2

    reserved_dir = find_reserved_dir(root)
    shard_paths = collect_shards(reserved_dir)

    file_meta: dict[str, tuple[int, int, int]] = {}
    dir_meta: dict[str, tuple[int, int]] = {}
    link_meta: dict[str, int] = {}

    try:
        for shard_path in shard_paths:
            with open(shard_path, "rb") as shard:
                if shard.read(len(MAGIC)) != MAGIC:
                    raise ValueError(f"not a shard file: {shard_path}")

                while True:
                    header = shard.read(RECORD.size)
                    if not header:
                        break
                    if len(header) != RECORD.size:
                        raise ValueError(f"truncated record in {shard_path}")

                    kind, path_len, mode, mtime_ns, offset, total_size, data_len = (
                        RECORD.unpack(header)
                    )
                    path_bytes = shard.read(path_len)
                    data = shard.read(data_len)
                    if len(path_bytes) != path_len or len(data) != data_len:
                        raise ValueError(f"truncated record in {shard_path}")

                    rel_path = path_bytes.decode("utf-8")
                    dest = safe_join(root, rel_path)
                    parent = os.path.dirname(dest)
                    if parent:
                        os.makedirs(parent, exist_ok=True)

                    if kind == TYPE_FILE:
                        if offset == 0 and data_len == 0:
                            # Empty file (or a zero-length final piece).
                            with open(dest, "wb"):
                                pass
                        else:
                            fd = os.open(
                                dest, os.O_WRONLY | os.O_CREAT, 0o600
                            )
                            try:
                                os.pwrite(fd, data, offset)
                            finally:
                                os.close(fd)
                        if dest not in file_meta:
                            file_meta[dest] = (mode, mtime_ns, total_size)

                    elif kind == TYPE_DIR:
                        os.makedirs(dest, exist_ok=True)
                        dir_meta[dest] = (mode, mtime_ns)

                    elif kind == TYPE_LINK:
                        target = data.decode("utf-8")
                        create_symlink(dest, target)
                        link_meta[dest] = mtime_ns

                    else:
                        raise ValueError(
                            f"unknown record type {kind!r} in {shard_path}"
                        )

        # Verify every reconstructed file has the recorded size.
        for path, (_mode, _mtime_ns, expected_size) in file_meta.items():
            actual_size = os.path.getsize(path)
            if actual_size != expected_size:
                raise ValueError(
                    f"size mismatch for {path}: "
                    f"expected {expected_size}, got {actual_size}"
                )

        # Restore file permissions and timestamps.
        for path, (mode, mtime_ns, _size) in file_meta.items():
            os.chmod(path, stat.S_IMODE(mode) & 0o7777)
            os.utime(path, ns=(mtime_ns, mtime_ns))

        # Restore symlink timestamps where the platform supports it.
        for path, mtime_ns in link_meta.items():
            try:
                os.utime(path, ns=(mtime_ns, mtime_ns), follow_symlinks=False)
            except (OSError, NotImplementedError):
                pass

        # Restore directory metadata deepest-first so parent timestamps stick.
        for path in sorted(
            dir_meta, key=lambda item: item.count(os.sep), reverse=True
        ):
            mode, mtime_ns = dir_meta[path]
            os.chmod(path, stat.S_IMODE(mode) & 0o7777)
            os.utime(path, ns=(mtime_ns, mtime_ns))

    except (OSError, ValueError, UnicodeDecodeError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1

    shutil.rmtree(reserved_dir)
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))

